11		"github.com/entireio/cli/cmd/entire/cli/settings"
12	)
13	
14	// CountUnpushedCheckpoints approximates how many checkpoints exist locally
15	// but not on the checkpoint sync remote. Fully local — no network.
16	// git-refs primary: push-queue length. git-branch primary: v1 commits ahead
17	// of refs/remotes/<remote>/<v1>; an absent tracking ref with a local v1
18	// branch counts every v1 commit (correct for the deferred-publish case; a
19	// stale tracking ref overcounts — acceptable for a local, no-network
20	// heuristic).
21	func CountUnpushedCheckpoints(ctx context.Context, remoteName string) (int, error) {
22		if cpCfg, _ := settings.LoadCheckpointsConfig(ctx); checkpoint.PrimaryIsRefs(cpCfg) { //nolint:errcheck // fail-soft like prePush: a bad checkpoints block defaults to the git-branch backend
23			return countQueuedCheckpointRefs(ctx)
24		}
25		return countUnpushedV1Commits(ctx, remoteName)
26	}
27	
28	// countQueuedCheckpointRefs returns the push-discovery queue length (git-refs
29	// backend): every queued ref is a checkpoint written locally but not yet
30	// confirmed pushed.
31	func countQueuedCheckpointRefs(ctx context.Context) (int, error) {
32		repo, err := OpenRepository(ctx)
33		if err != nil {
34			return 0, fmt.Errorf("open repository: %w", err)
35		}
36		defer repo.Close()
37	
38		queue, err := checkpoint.PushQueueForRepo(ctx, repo)
39		if err != nil {
40			return 0, fmt.Errorf("resolve push queue: %w", err)
41		}
42		refs, err := queue.Peek()
43		if err != nil {
44			return 0, fmt.Errorf("read push queue: %w", err)
45		}
46		return len(refs), nil
47	}
48	
49	// countUnpushedV1Commits counts v1-branch commits not on the remote-tracking
50	// ref (git-branch backend). No local v1 branch means nothing to push (0).
51	func countUnpushedV1Commits(ctx context.Context, remoteName string) (int, error) {
52		local := checkpoint.ResolveRefs(ctx).Primary
53		if !gitCommitRefExists(ctx, local.String()) {
54			return 0, nil
55		}
56		rangeSpec := local.String()
57		if remoteName != "" {
58			tracking := "refs/remotes/" + remoteName + "/" + local.Short()
59			if gitCommitRefExists(ctx, tracking) {
60				rangeSpec = tracking + ".." + local.String()
61			}
62		}
63		out, err := exec.CommandContext(ctx, "git", "rev-list", "--count", rangeSpec).Output()
64		if err != nil {
